import{c as t,Z as e,Q as i,j as l,m as r,o as n}from"./chunks/framework.DOi4mjdC.js";const m=JSON.parse('{"title":"一剪梅·红藕香残玉簟秋","description":"","frontmatter":{"title":"一剪梅·红藕香残玉簟秋","author":"李清照","dynasty":"宋"},"headers":[],"relativePath":"books/shici/songci/8.md","filePath":"books/shici/songci/8.md"}'),s={name:"books/shici/songci/8.md"};function h(u,a,c,q,p,d){const o=e("PoemNav");return i(),l("div",null,[a[0]||(a[0]=r('<h1 id="一剪梅·红藕香残玉簟秋" tabindex="-1">一剪梅·红藕香残玉簟秋 <a class="header-anchor" href="#一剪梅·红藕香残玉簟秋" aria-label="Permalink to &quot;一剪梅·红藕香残玉簟秋&quot;">​</a></h1><p><strong>[宋] <a href="/authors/liqingzhao.html">李清照</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>红藕香残玉簟秋。轻解罗裳，独上兰舟。云中谁寄锦书来？雁字回时，月满西楼。</p><p>花自飘零水自流。一种相思，两处闲愁。此情无计可消除，才下眉头，却上心头。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>一剪梅：词牌名</li><li>红藕：红色的荷花</li><li>玉簟：光滑如玉的竹席</li><li>罗裳：丝绸做的衣裳</li><li>兰舟：木兰木做的船，船的美称</li><li>锦书：书信的美称</li><li>雁字：大雁飞行时排成的队形，古人认为大雁能传书</li><li>西楼：指词人居住的地方</li><li>闲愁：无端无谓的忧愁</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>红色的荷花已经凋谢，香气残留，如玉的竹席透出秋意。轻轻脱下丝绸衣裳，独自登上小船。云中是谁寄来了书信？大雁排成队飞回时，月光洒满了西楼。</p><p>花儿自顾自地飘落，水自顾自地流淌。同样的相思之情，分隔两地的无端忧愁。这种情意没有办法消除，刚从眉头舒展，却又涌上了心头。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首词是李清照前期的代表作，写于与丈夫赵明诚离别之后，表达了对丈夫的深切思念之情。</p><p>上片写秋景和盼信的心情。&quot;红藕香残玉簟秋&quot;，以荷花凋谢、竹席生凉点明秋意，也暗示了词人内心的凄凉。&quot;轻解罗裳，独上兰舟&quot;，写词人独自泛舟的情景，&quot;独&quot;字点出孤独之感。&quot;云中谁寄锦书来？雁字回时，月满西楼&quot;，写词人盼望丈夫来信的心情。大雁传书的典故，月光满楼的景象，将思念之情渲染得缠绵悱恻。</p><p>下片写相思之情。&quot;花自飘零水自流&quot;，以花落水流比喻时光流逝和离别之苦。&quot;一种相思，两处闲愁&quot;，写夫妻虽然分隔两地，却同样承受着相思之苦。&quot;此情无计可消除，才下眉头，却上心头&quot;，是全词的名句。词人用细腻的笔触，将无形的相思之情化为有形的动态，&quot;眉头&quot;与&quot;心头&quot;的转换，生动地表现了愁绪的难以排遣。</p><p>全词语言清丽，情感真挚，将离别相思之情写得委婉动人，是李清照婉约词风的典型代表。</p><hr><h2 id="关于作者" tabindex="-1">关于作者 <a class="header-anchor" href="#关于作者" aria-label="Permalink to &quot;关于作者&quot;">​</a></h2><blockquote><p><strong>李清照</strong>（1084年－约1155年），号易安居士，宋代著名女词人，婉约词派代表，有&quot;千古第一才女&quot;之称。其词前期多写悠闲生活，后期多悲叹身世。</p><p><a href="/authors/liqingzhao.html">查看作者详情 →</a></p></blockquote>',18)),n(o)])}const b=t(s,[["render",h]]);export{m as __pageData,b as default};
